<?php
namespace Tests\Feature;
use App\Models\Instansi;use App\Models\KategoriInstansi;use App\Models\Pembinaan;use App\Models\PembinaanFile;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class PembinaanFileCatalogFeatureTest extends TestCase {use RefreshDatabase;private function make(User $u,string $name,string $service): array{$c=KategoriInstansi::create(['nama'=>$name.' Cat','status_aktif'=>true]);$i=Instansi::create(['kategori_instansi_id'=>$c->id,'nama'=>$name.' Inst','status_aktif'=>true]);$p=Pembinaan::create(['instansi_id'=>$i->id,'created_by'=>$u->id,'tanggal_mulai'=>'2026-10-01','metode_pelaksanaan'=>'Daring','layanan'=>$service,'status_dokumen'=>'Tahap Persiapan']);$f=PembinaanFile::create(['pembinaan_id'=>$p->id,'uploaded_by'=>$u->id,'jenis'=>'materi','nama_asli'=>$name.'.pdf','path'=>'p/'.$name,'mime_type'=>'application/pdf','ukuran'=>100,'visibilitas'=>'Private']);return[$i,$p,$f];}
public function test_guest_rejected_and_roles_scoped():void{$owner=User::factory()->role('pelaksana')->create();$other=User::factory()->role('pelaksana')->create();[,,$mine]=$this->make($owner,'Mine','Mine Service');[,,$foreign]=$this->make($other,'Foreign','Foreign Service');$this->get('/katalog-file')->assertRedirect('/login');$this->actingAs($owner)->get('/katalog-file')->assertOk()->assertSee('Mine.pdf')->assertDontSee('Foreign.pdf');foreach([User::factory()->role('admin')->create(),User::factory()->role('monitoring')->create()] as $user)$this->actingAs($user)->get('/katalog-file')->assertSee('Mine.pdf')->assertSee('Foreign.pdf');}
public function test_search_filters_pagination_and_download_link():void{$u=User::factory()->role('pelaksana')->create();[$i,,$file]=$this->make($u,'Search','Needle Service');$this->actingAs($u)->get('/katalog-file?q=Needle&jenis=materi&visibilitas=Private&instansi_id='.$i->id)->assertSee('Search.pdf')->assertSee(route('pembinaan.files.download',$file));$this->get('/katalog-file?q=NoResult')->assertSee('Belum ada file yang sesuai.');}
}
